package com.campusiq.platform.entity; import com.campusiq.user.entity.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="user_platform_accounts",uniqueConstraints=@UniqueConstraint(name="uk_user_platform",columnNames={"user_id","platform"})) public class UserPlatformAccount { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Enumerated(EnumType.STRING) @Column(nullable=false) private Platform platform; @Column(nullable=false) private String username; private String externalUserId; @Enumerated(EnumType.STRING) @Column(nullable=false) private AccountStatus status; private Instant verifiedAt; private Instant lastSyncedAt; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();} public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public Platform getPlatform(){return platform;} public void setPlatform(Platform v){platform=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public AccountStatus getStatus(){return status;} public void setStatus(AccountStatus v){status=v;} public Instant getVerifiedAt(){return verifiedAt;} public void setVerifiedAt(Instant v){verifiedAt=v;} public Instant getLastSyncedAt(){return lastSyncedAt;} public void setLastSyncedAt(Instant v){lastSyncedAt=v;} }
